  // state top level). A mismatch is a current-observation loss, not a normal
  // scene -- even when both sides share the same wrong value (V06/C04/C06).
  if (snapshot.session_id != null && state.session_id != null &&
      snapshot.session_id !== state.session_id)
    return { ok: false, reason: "session_mismatch" };
