// The current target's own explicit geometry for the active mode. A snapshot
// candidate that is not bound to the target must never stand in for it: with
// no matching identifier a candidate is not "the target", so no first/nearest
// pick and no tracking (V07/C07).
function hfTargetGeometryPresent() {
  var s = hf.lastState;
  if (!s) return false;
  if (hf.coordMode === "ground") {
    return HF.isTriple(s.position_ground_m) || HF.isTriple(s.center_ground_m) ||
      (s.bbox_ground_from === "actual_points" &&
       HF.isTriple(s.bbox_ground_min_m) && HF.isTriple(s.bbox_ground_max_m));
  }
  return HF.isTriple(s.position_source_m) ||
    (HF.isTriple(s.bbox_source_min_m) && HF.isTriple(s.bbox_source_max_m));
}

