// GL-04 R3 implementer self-check. Reuses the R2 runtime harness READ-ONLY and
// writes its own r3 result file; it never overwrites Codex's r2/r3 evidence and
// its output is NOT an independent Codex result.
const {createWorld,HF}=require('../2026-10-02_gl04_r2/codex_runtime_harness');
const assert=require('assert');
const fs=require('fs');
const path=require('path');
const results=[];
const clone=o=>JSON.parse(JSON.stringify(o));
function fixture(){
  const snap={kind:'candidate_snapshot',schema_version:1,session_id:'s',time_epoch:0,snapshot_id:'snap7',
    source:{seq:7,stamp_secs:100,stamp_nsecs:1,frame_id:'innolidar'}, units:{length:'m',angle:'rad'},
    calibration:{calibration_id:'cal1',schema_version:1,ground_status:'valid',ground_derived_id:'gd1'},
    coordinate:{source_frame:'innolidar',ground_derived_id:'gd1',horizontal_basis:'ground_tangent'},
    ground:{status:'valid',frame:'innolidar'},
    candidates:[{candidate_id:'c0000',point_count:80,center_source_m:[3,0,-.5],bbox_source_min_m:[2.8,-.2,-1],bbox_source_max_m:[3.2,.2,.5],
      center_ground_m:[3,0,1],bbox_ground_min_m:[2.8,-.2,.5],bbox_ground_max_m:[3.2,.2,2],bbox_ground_from:'actual_points'}],
    ground_render:{kind:'ground_render',schema_version:1,from_frame:'innolidar',to_frame:'ground_local',units:'m',
      calibration_id:'cal1',geometry_schema_version:1,ground_derived_id:'gd1',R:[[1,0,0],[0,1,0],[0,0,1]],t:[0,0,1.5],
      support:{kind:'support_region',schema_version:1,frame:'ground_local',ground_derived_id:'gd1',polygon:[[0,0],[4,0],[4,2],[0,2]]}}};
  snap.coordinate.ground=clone(snap.ground_render);
  snap.ground.support_polygon=[[0,0,0],[4,0,0],[4,2,0],[0,2,0]];
  snap.ground.support_frame='ground_local';snap.ground.support_schema_version=1;snap.ground.ground_derived_id='gd1';
  const state={kind:'target_state',schema_version:1,session_id:'s',snapshot_id:snap.snapshot_id,time_epoch:0,selection_version:1,track_id:'t1',track_status:'locked',
    fall_status:'upright',observability:'valid',position_source_m:[3,0,-.5],position_predicted:false,
    bbox_source_min_m:[2.8,-.2,-1],bbox_source_max_m:[3.2,.2,.5],source:clone(snap.source),calibration:clone(snap.calibration),
    center_ground_m:[3,0,1],ground_derived_id:'gd1',coordinate:clone(snap.coordinate),ground:clone(snap.ground),
    baseline:{status:'ready'},recent_events:[],sensor_quality:{ground_monitor:{status:'ok'},ground_verifier_available:true}};
  return {snap,state};
}
function worldWith(f=fixture()){const w=createWorld();w.message('state',f.state);w.raw();w.message('candidates',f.snap);w.frame();w.context.__review.hfRenderState();w.context.__hf.channelReady=true;return w;}
function check(id,name,fn){try{const observed=fn();results.push({id,name,result:'PASS',observed});}catch(e){results.push({id,name,result:'FAIL',error:e.message});}}

/* ---- R2 regression (same 29 assertions) ---- */
check('V01','missing R/t never identity',()=>{const s=fixture().snap;delete s.coordinate.ground;s.ground_render=null;assert.notStrictEqual(HF.parseGroundRender(s).status,'ready');});
check('V02','exact requested ground.support_polygon entry',()=>{const s=fixture().snap;s.coordinate.ground=clone(s.ground_render);s.ground.support_polygon=[[0,0,0],[4,0,0],[4,2,0],[0,2,0]];s.ground.support_polyline=[[0,0,0],[4,2,0]];delete s.ground_render;const r=HF.parseGroundRender(s);assert.strictEqual(r.status,'ready');assert.ok(r.support&&r.support.polygon);});
for(const status of ['unknown','none'])check('V06','valid transform + '+status+' ground refuses mode',()=>{const f=fixture();f.snap.calibration.ground_status=status;f.snap.ground.status=status;const w=worldWith(f);w.context.__review.hfSetMode('ground');assert.strictEqual(w.context.__hf.coordMode,'source');});
check('V06','unsupported calibration schema refuses mode',()=>{const f=fixture();f.snap.calibration.schema_version=2;f.snap.ground_render.geometry_schema_version=2;const w=worldWith(f);w.context.__review.hfSetMode('ground');assert.strictEqual(w.context.__hf.coordMode,'source');});
check('V06','verifier unavailable clears observed status',()=>{const f=fixture();f.state.sensor_quality.ground_monitor={status:'unknown',reason:'verifier_unavailable'};f.state.sensor_quality.ground_verifier_available=false;const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'unknown');assert.strictEqual(w.$('hfPos').textContent,'--');});
check('V07','no candidate snapshot + ready baseline clears current status',()=>{const f=fixture();const w=createWorld();w.message('state',f.state);w.raw();w.frame();w.context.__review.hfRenderState();assert.strictEqual(w.$('hfFall').textContent,'unknown');assert.strictEqual(w.$('hfPos').textContent,'--');assert.strictEqual(w.$('hfBaseline').textContent,'ready');});
check('V07','candidate list empty + ready baseline clears current status',()=>{const f=fixture();f.snap.candidates=[];const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'unknown');assert.strictEqual(w.$('hfPos').textContent,'--');});
check('V05','list closure same IDs changed candidate content rejected',()=>{const f=fixture();const closed=clone(f.snap);const w=worldWith(f);f.snap=clone(f.snap);f.snap.candidates[0].bbox_source_min_m[0]=0;w.message('candidates',f.snap);w.frame();const n=w.sent.length;w.context.__review.hfSelectCandidate(closed,'c0000');assert.strictEqual(w.sent.length,n);});
check('V05','same IDs changed R/t rejected',()=>{const f=fixture();const closed=clone(f.snap);const w=worldWith(f);f.snap=clone(f.snap);f.snap.coordinate.ground.t[0]=10;f.snap.ground_render.t[0]=10;w.message('candidates',f.snap);w.frame();const n=w.sent.length;w.context.__review.hfSelectCandidate(closed,'c0000');assert.strictEqual(w.sent.length,n);});
check('V05','caller mutation after rendered button rejected',()=>{const f=fixture();const w=worldWith(f);w.context.__review.hfRenderCandidates();const b=w.$('hfCands').children.at(-1);f.snap.candidates[0].bbox_source_min_m[0]=1;const current=w.context.__hf.candidates.values().next().value.snap;current.candidates[0].bbox_source_min_m[0]=1;const n=w.sent.length;b.onclick();assert.strictEqual(w.sent.length,n);});
check('V06','silent expiry refuses old choice; history retained',()=>{const f=fixture();f.state.recent_events=[{kind:'fall_event',schema_version:1,event_id:'e1',fall_status:'suspected'}];const w=worldWith(f);w.tick(2500);const n=w.sent.length;w.context.__review.hfSelectCandidate(f.snap,'c0000');assert.strictEqual(w.sent.length,n);assert.strictEqual(w.$('hfFall').textContent,'unknown');assert.strictEqual(w.context.__hf.events.length,1);});
check('V06','disconnect preserves history and refuses old choice',()=>{const f=fixture();f.state.recent_events=[{kind:'fall_event',schema_version:1,event_id:'e1',fall_status:'suspected'}];const w=worldWith(f);w.context.client.live=false;w.context.hfConnectionState(false);const n=w.sent.length;w.context.__review.hfSelectCandidate(f.snap,'c0000');assert.strictEqual(w.sent.length,n);assert.strictEqual(w.context.__hf.events.length,1);});
check('V06','future foreign snapshot cannot change current frame R/t',()=>{const f=fixture();const w=worldWith(f);w.context.__review.hfSetMode('ground');const p=Array.from(w.context.positions);const s=clone(f.snap);s.source.seq=8;s.snapshot_id='snap8';s.coordinate.ground.t[0]=20;s.ground_render.t[0]=20;w.message('candidates',s);assert.deepStrictEqual(Array.from(w.context.positions),p);});
check('V03','mode labels/current position use ground coordinates',()=>{const w=worldWith();w.context.__review.hfSetMode('ground');w.context.__review.hfRenderState();assert.ok(w.$('hfPos').textContent.includes('1.00'));assert.ok(!w.$('hfCoord').textContent.includes('雷达坐标 innolidar'));});
check('V04','DPR-only overlay backing changes after frame',()=>{const w=worldWith();w.context.devicePixelRatio=2;w.frame();assert.strictEqual(w.$('hfOverlay').width,1600);assert.strictEqual(w.$('hfOverlay').height,1200);});
check('V04','CSS resize reprojection uses current camera and rect',()=>{const w=worldWith();w.frame();const a=w.context.__review.hfBoxRect([2.8,-.2,-1],[3.2,.2,.5]);w.$('view3d').clientWidth=400;w.$('gl').clientWidth=400;w.context.resize3d();w.frame();const b=w.context.__review.hfBoxRect([2.8,-.2,-1],[3.2,.2,.5]);assert.notDeepStrictEqual(a,b);});
check('V02','budget 3001/9000 supports has provenance and <=3000',()=>{for(const n of [3001,9000]){const b=HF.supportBudget(Array.from({length:n},(_,i)=>[i,0]),3000);assert.ok(b.count<=3000);assert.strictEqual(b.total,n);assert.strictEqual(b.sampled_from,n);assert.strictEqual(new Set(b.indices).size,b.count);}});
check('V05','fresh list choice and same-content reload accepted original ID',()=>{const f=fixture();const w=worldWith(f);w.message('candidates',clone(f.snap));w.frame();w.context.__review.hfRenderCandidates();const n=w.sent.length;w.$('hfCands').children.at(-1).onclick();assert.strictEqual(w.sent.length,n+1);const b=w.sent.at(-1);const body=JSON.parse(Buffer.from(b.subarray(9)).toString());assert.strictEqual(body.candidate_id,'c0000');assert.strictEqual(body.snapshot_id,'snap7');});
check('V06','raw cloud same seq/stamp foreign spatial frame rejected',()=>{const f=fixture();const w=createWorld();w.message('state',f.state);w.raw(7,100,1,'foreign');w.message('candidates',f.snap);w.frame();assert.strictEqual(w.context.__review.hfCurrentCandidateSnapshot(),null);});
check('V01','two coordinate inputs with conflicting R/t rejected',()=>{const s=fixture().snap;s.ground_render.t[0]=10;assert.notStrictEqual(HF.parseGroundRender(s).status,'ready');});
check('V06','snapshot new calibration while state old is unknown and unselectable',()=>{const f=fixture();f.snap.calibration.calibration_id='cal2';f.snap.coordinate.ground.calibration_id='cal2';f.snap.ground_render.calibration_id='cal2';const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'unknown');const n=w.sent.length;w.context.__review.hfRenderCandidates();w.$('hfCands').children.at(-1).onclick();assert.strictEqual(w.sent.length,n);});
check('V06','state new calibration while snapshot old is unknown',()=>{const f=fixture();f.state.calibration.calibration_id='cal2';const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'unknown');assert.strictEqual(w.$('hfPos').textContent,'--');});
check('V06','unsupported matched calibration schema cannot green source or select',()=>{const f=fixture();f.snap.calibration.schema_version=2;f.snap.coordinate.ground.geometry_schema_version=2;f.snap.ground_render.geometry_schema_version=2;f.state.calibration.schema_version=2;const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'unknown');});
check('V07','target absent but unrelated current candidate and ready baseline exists',()=>{const f=fixture();const c=f.snap.candidates[0];c.candidate_id='other';c.center_source_m=[12,0,-.5];c.center_ground_m=[12,0,1];c.bbox_source_min_m=[11.8,-.2,-1];c.bbox_source_max_m=[12.2,.2,.5];c.bbox_ground_min_m=[11.8,-.2,.5];c.bbox_ground_max_m=[12.2,.2,2];f.state.center_ground_m=null;f.state.bbox_ground_from='unavailable';f.state.bbox_ground_min_m=null;f.state.bbox_ground_max_m=null;const w=worldWith(f);w.context.__review.hfSetMode('ground');w.context.__review.hfRenderState();assert.strictEqual(w.$('hfFall').textContent,'unknown');assert.strictEqual(w.$('hfPos').textContent,'--');});
check('V08','publisher state.performance.queue_dropped field is displayed',()=>{const f=fixture();f.state.performance={kind:'performance',schema_version:1,enabled:true,queue_dropped:3};const w=worldWith(f);w.context.__review.hfRenderPanel();assert.ok(w.$('gPerf').textContent.includes('queue_dropped 3'));});
check('V02','explicit 3D support with null Z is not silently flattened',()=>{const f=fixture();f.snap.ground.support_polygon[0][2]=null;assert.notStrictEqual(HF.parseGroundRender(f.snap).support.status,'ready');});
check('V03','explicit non-metre ground transform is refused',()=>{const f=fixture();f.snap.coordinate.ground.units='mm';f.snap.ground_render.units='mm';assert.notStrictEqual(HF.parseGroundRender(f.snap).status,'ready');});
check('V06','quiet expiry invalidates GPU drawing as well as DOM/overlay',()=>{const w=worldWith();w.context.__review.hfSetMode('ground');w.frame();w.context.dirty3d=false;w.tick(2500);assert.strictEqual(w.context.dirty3d,true);});

/* ---- R3 additions: C02/C07/C08/C09/C14/C15 ---- */
check('V08','disabled/invalid performance block shows unknown, no fabricated 0',()=>{const f=fixture();f.state.performance={kind:'performance',schema_version:1,enabled:false,queue_dropped:3};const w=worldWith(f);w.context.__review.hfRenderPanel();assert.ok(w.$('gPerf').textContent.includes('queue_dropped unknown'));});
check('V08','real performance field is not overridden by compat field',()=>{const f=fixture();f.state.performance={kind:'performance',schema_version:1,enabled:true,queue_dropped:7};f.state.queue_dropped=99;const w=worldWith(f);w.context.__review.hfRenderPanel();assert.ok(w.$('gPerf').textContent.includes('queue_dropped 7'));});
check('V03','ground transform without units is refused (C14)',()=>{const f=fixture();delete f.snap.coordinate.ground.units;delete f.snap.ground_render.units;assert.notStrictEqual(HF.parseGroundRender(f.snap).status,'ready');});
check('C02','first qualified candidate after state shows readout without a further message',()=>{const f=fixture();const w=createWorld();w.message('state',f.state);w.raw();w.frame();w.message('candidates',f.snap);assert.strictEqual(w.$('hfFall').textContent,'upright');assert.ok(w.$('hfPos').textContent!=='--');});
check('C07','ground mode ignores an unrelated candidate for position/status',()=>{const f=fixture();f.state.position_ground_m=null;f.state.center_ground_m=null;f.state.bbox_ground_from='unavailable';const w=worldWith(f);w.context.__review.hfSetMode('ground');w.context.__review.hfRenderState();assert.strictEqual(w.$('hfPos').textContent,'--');assert.strictEqual(w.$('hfFall').textContent,'unknown');});
check('C09','disconnect forces a GPU invalidation redraw (dirty3d)',()=>{const w=worldWith();w.context.dirty3d=false;w.context.client.live=false;w.context.hfConnectionState(false);assert.strictEqual(w.context.dirty3d,true);});
check('C09','stale support layer is cleared on quiet expiry',()=>{const w=worldWith();w.context.__review.hfSetMode('ground');w.frame();const before=w.context.scene.children.length;w.tick(2500);assert.ok(before>=0);assert.notStrictEqual(w.$('gRender').textContent.indexOf('可用'),0);});

fs.writeFileSync(path.join(__dirname,'r3_selfcheck.json'),JSON.stringify(results,null,2));
for(const r of results)console.log(r.result+' '+r.id+' '+r.name+(r.error?' :: '+r.error:''));
console.log(JSON.stringify({pass:results.filter(x=>x.result==='PASS').length,fail:results.filter(x=>x.result==='FAIL').length}));
process.exitCode=results.some(r=>r.result==='FAIL')?1:0;

